# --- Canvas ------------------------------------------------------------
class Canvas:
    def __init__(self, w, h, bg):
        self.w, self.h = w, h
        self.px = bytearray(bytes(bg) * (w * h))

    def _off(self, x, y):
        return (y * self.w + x) * 3

    def set_pixel(self, x, y, color):
        if 0 <= x < self.w and 0 <= y < self.h:
            o = self._off(x, y)
            self.px[o:o + 3] = bytes(color)

    def fill_rect(self, x, y, w, h, color):
        x0, y0 = max(0, x), max(0, y)
        x1, y1 = min(self.w, x + w), min(self.h, y + h)
        if x1 <= x0 or y1 <= y0:
            return
        row = bytes(color) * (x1 - x0)
        for yy in range(y0, y1):
            o = self._off(x0, yy)
            self.px[o:o + len(row)] = row

    def rect_outline(self, x, y, w, h, color, width=2):
        self.fill_rect(x, y, w, width, color)
        self.fill_rect(x, y + h - width, w, width, color)
        self.fill_rect(x, y, width, h, color)
        self.fill_rect(x + w - width, y, width, h, color)

    def _plot(self, x, y, color, width):
        self.fill_rect(x - width // 2, y - width // 2, width, width, color)

    def line(self, x0, y0, x1, y1, color, width=1):
        """Bresenham line, plotted with width x width squares."""
        dx, dy = abs(x1 - x0), abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx - dy
        while True:
            self._plot(x0, y0, color, width)
            if x0 == x1 and y0 == y1:
                return
            e2 = 2 * err
            if e2 > -dy:
                err -= dy
                x0 += sx
            if e2 < dx:
                err += dx
                y0 += sy

    def ellipse(self, cx, cy, rx, ry, color, width=3, a0=0, a1=360):
        import math
        step = 3
        prev = None
        a = a0
        while a <= a1:
            rad = math.radians(a)
            px = cx + int(rx * math.cos(rad))
            py = cy + int(ry * math.sin(rad))
            if prev is not None:
                self.line(prev[0], prev[1], px, py, color, width)
            prev = (px, py)
            a += step
        if a1 - a0 >= 360:
            rad = math.radians(a0)
            self.line(prev[0], prev[1],
                      cx + int(rx * math.cos(rad)),
                      cy + int(ry * math.sin(rad)), color, width)

    def polygon(self, points, color):
        """Scanline-filled polygon."""
        n = len(points)
        ys = [p[1] for p in points]
        for y in range(min(ys), max(ys) + 1):
            xs = []
            for i in range(n):
                x0, y0 = points[i]
                x1, y1 = points[(i + 1) % n]
                if (y0 <= y < y1) or (y1 <= y < y0):
                    xs.append(x0 + (y - y0) * (x1 - x0) / (y1 - y0))
            xs.sort()
            for i in range(0, len(xs) - 1, 2):
                self.fill_rect(int(xs[i]), y, int(xs[i + 1]) - int(xs[i]) + 1,
                               1, color)


# --- Bitmap text --------------------------------------------------------
def glyph(table, ch):
    return table.get(ch, table["?"])


def text_width(text, table, scale=1):
    return sum(glyph(table, c)[0] for c in text) * scale


def draw_text(cv, x, y, text, table, cell_h, scale, color):
    """Draw text with the top of the cell at y. Returns width drawn."""
    pen = x
    for ch in text:
        adv, w, xoff, hexs = glyph(table, ch)
        if w and hexs:
            hexlen = ((w + 3) // 4 * 4) // 4
            gx = pen + xoff * scale
            for r in range(cell_h):
                bits = int(hexs[r * hexlen:(r + 1) * hexlen] or "0", 16)
                if not bits:
                    continue
                # Expand set bits into runs for fewer fill calls.
                run_start = None
                for bx in range(w):
                    bit = (bits >> ((w + 3) // 4 * 4 - 1 - bx)) & 1
                    if bit and run_start is None:
                        run_start = bx
                    elif not bit and run_start is not None:
                        cv.fill_rect(gx + run_start * scale,
                                     y + r * scale,
                                     (bx - run_start) * scale, scale, color)
                        run_start = None
                if run_start is not None:
                    cv.fill_rect(gx + run_start * scale, y + r * scale,
                                 (w - run_start) * scale, scale, color)
        pen += adv * scale
    return pen - x


def draw_text_anchor(cv, x, y, text, table, cell_h, scale, color,
                     anchor="la"):
    w = text_width(text, table, scale)
    if anchor == "ra":
        x -= w
    elif anchor == "mm":
        x -= w // 2
    draw_text(cv, x, y, text, table, cell_h, scale, color)


def wrap(cv, text, table, scale, max_width):
    lines, line = [], ""
    for word in text.split():
        trial = f"{line} {word}".strip()
        if text_width(trial, table, scale) <= max_width:
            line = trial
        else:
            if line:
                lines.append(line)
            line = word
    if line:
        lines.append(line)
    return lines


def draw_lines(cv, lines, x, y, table, cell_h, scale, color, leading):
    for line in lines:
        draw_text(cv, x, y, line, table, cell_h, scale, color)
        y += leading
    return y


# --- Icons (drawn with primitives) --------------------------------------
def draw_globe(cv, cx, cy, r, color):
    cv.ellipse(cx, cy, r, r, color, 5)
    cv.ellipse(cx, cy, r // 2, r, color, 3)
    cv.ellipse(cx, cy, int(r * 0.86), int(r * 0.5), color, 3)
    cv.line(cx - r, cy, cx + r, cy, color, 3)
    cv.ellipse(cx, cy, r, r, RED, 5, a0=200, a1=340)


def draw_bridge(cv, cx, cy, s, color):
    x0, y0 = cx - s // 2, cy - s // 2
    cv.line(x0, y0 + int(s * 0.72), x0 + s, y0 + int(s * 0.72), color, 4)
    cv.ellipse(cx, y0 + int(s * 0.44), int(s * 0.42), int(s * 0.34),
               color, 4, a0=180, a1=360)
    for fx in (0.22, 0.5, 0.78):
        x = x0 + int(s * fx)
        cv.line(x, y0 + int(s * 0.30), x, y0 + int(s * 0.72), color, 3)
    cv.line(x0 + int(s * 0.08), y0 + int(s * 0.30),
            x0 + int(s * 0.08), y0 + int(s * 0.72), color, 4)
    cv.line(x0 + int(s * 0.92), y0 + int(s * 0.30),
            x0 + int(s * 0.92), y0 + int(s * 0.72), color, 4)


def draw_ship(cv, cx, cy, s, color):
    x0, y0 = cx - s // 2, cy - s // 2
    cv.polygon([(x0, y0 + int(s * 0.55)), (x0 + s, y0 + int(s * 0.55)),
                (x0 + int(s * 0.86), y0 + int(s * 0.82)),
                (x0 + int(s * 0.14), y0 + int(s * 0.82))], color)
    cv.fill_rect(x0 + int(s * 0.60), y0 + int(s * 0.28),
                 int(s * 0.18), int(s * 0.27), color)
    cv.line(x0 + int(s * 0.68), y0 + int(s * 0.16),
            x0 + int(s * 0.68), y0 + int(s * 0.28), color, 3)
    for wx in (0.14, 0.42, 0.70):
        cv.ellipse(x0 + int(s * (wx + 0.11)), y0 + int(s * 0.92),
                   int(s * 0.11), int(s * 0.06), color, 3, a0=0, a1=180)


def draw_pin(cv, cx, cy, s, color):
    x0, y0 = cx - s // 2, cy - s // 2
    cv.ellipse(cx, y0 + int(s * 0.34), int(s * 0.32), int(s * 0.28),
               color, 4)
    cv.fill_rect(cx - int(s * 0.12), y0 + int(s * 0.24),
                 int(s * 0.24), int(s * 0.22), color)
    cv.polygon([(x0 + int(s * 0.30), y0 + int(s * 0.52)),
                (x0 + int(s * 0.70), y0 + int(s * 0.52)),
                (cx, y0 + int(s * 0.94))], color)


def draw_jet(cv, cx, cy, s, color):
    x0, y0 = cx - s // 2, cy - s // 2
    cv.polygon([(x0 + int(s * 0.10), y0 + int(s * 0.52)),
                (x0 + int(s * 0.90), y0 + int(s * 0.08)),
                (x0 + int(s * 0.66), y0 + int(s * 0.56)),
                (x0 + int(s * 0.90), y0 + int(s * 0.92)),
                (x0 + int(s * 0.52), y0 + int(s * 0.68))], color)


ICONS = {"bridge": draw_bridge, "ship": draw_ship,
         "pin": draw_pin, "jet": draw_jet}


# --- Story card -----------------------------------------------------------
def story_card(cv, x, y, w, h, kicker, headline, sub, color, icon):
    cv.fill_rect(x, y, w, h, CARD)
    cv.rect_outline(x, y, w, h, RULE, 2)
    cv.fill_rect(x, y, w, 7, color)
    pad = 16
    tx = x + pad
    tw = w - 2 * pad
    icon_cx = x + w - pad - 22
    icon_cy = y + 30
    cv.ellipse(icon_cx, icon_cy, 24, 24, color, 3)
    ICONS[icon](cv, icon_cx, icon_cy, 34, color)
    draw_text(cv, tx, y + 16, kicker, FONT_SANS, H_SANS, 1, color)
    hlines = wrap(cv, headline, FONT_SERIF, 1, tw)[:2]
    cy = draw_lines(cv, hlines, tx, y + 42, FONT_SERIF, H_SERIF, 1, INK, 52)
    slines = wrap(cv, sub, FONT_SANS, 1, tw)[:2]
    draw_lines(cv, slines, tx, y + 152, FONT_SANS, H_SANS, 1, SUB, 25)


# --- PNG encoding ---------------------------------------------------------
def png_bytes(cv):
    raw = bytearray()
    stride = W * 3
    for y in range(H):
        raw.append(0)
        raw += cv.px[y * stride:(y + 1) * stride]
    comp = zlib.compress(bytes(raw), 9)

    def chunk(tag, data):
        out = struct.pack(">I", len(data)) + tag + data
        return out + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)

    ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr)
            + chunk(b"IDAT", comp) + chunk(b"IEND", b""))


# --- Page -------------------------------------------------------------------
def main():
    cv = Canvas(W, H, PAPER)

    # Masthead
    cv.fill_rect(0, 0, W, 148, NAVY)
    cv.fill_rect(0, 148, W, 4, RED)
    draw_text(cv, MARGIN, 26, "WORLD NEWS", FONT_SERIF, H_SERIF, 2, WHITE)
    draw_text_anchor(cv, W - MARGIN, 34, "TUESDAY", FONT_SANS, H_SANS, 1,
                     WHITE, anchor="ra")
    draw_text_anchor(cv, W - MARGIN, 66, "17 NOV 2026", FONT_SANS, H_SANS,
                     1, GOLD, anchor="ra")
    draw_text(cv, MARGIN, 118, "THE WORLD IN ONE PAGE", FONT_SANS, H_SANS,
              1, (178, 190, 210))
    draw_text_anchor(cv, W - MARGIN, 118, "SIX STORIES THAT MATTERED",
                     FONT_SANS, H_SANS, 1, (178, 190, 210), anchor="ra")

    # Red date strip
    cv.fill_rect(0, 152, W, 38, RED)
    draw_text_anchor(cv, W // 2, 163,
                     "TUESDAY, 17 NOVEMBER 2026  \u2022  THE DAY'S WORLD NEWS",
                     FONT_SANS, H_SANS, 1, WHITE, anchor="mm")

    # Lead story
    hx, hy, hw, hh = MARGIN, 204, W - 2 * MARGIN, 224
    cv.fill_rect(hx, hy, hw, hh, CARD)
    cv.rect_outline(hx, hy, hw, hh, RULE, 2)
    cv.fill_rect(hx, hy, 10, hh, RED)
    draw_globe(cv, hx + hw - 108, hy + hh // 2 + 6, 82, NAVY_LIGHT)
    tx = hx + 30
    tw = hw - 30 - 220
    draw_text(cv, tx, hy + 20, "LEAD STORY  \u2014  DIPLOMACY IN ASIA",
              FONT_SANS, H_SANS, 1, RED)
    hlines = wrap(cv, "Trump heads to Asia to meet Xi and Putin",
                  FONT_SERIF, 1, tw)[:2]
    cy = draw_lines(cv, hlines, tx, hy + 52, FONT_SERIF, H_SERIF, 1, INK, 54)
    slines = wrap(cv,
                  "The three leaders meet in Shenzhen on 19 November, "
                  "with nuclear risks, sanctions and Ukraine on the agenda.",
                  FONT_SANS, 1, tw)[:2]
    draw_lines(cv, slines, tx, cy + 10, FONT_SANS, H_SANS, 1, SUB, 25)

    # Grid of four stories
    grid_y = 442
    col_w = (W - 2 * MARGIN - 16) // 2
    row_h = 208
    stories = [
        ("WAR IN UKRAINE", "Bridges become the battlefield",
         "Ukraine hits Crimea bridge; Russia hits two Kyiv bridges in "
         "a record drone raid.", RED_LIGHT, "bridge"),
        ("MIDDLE EAST", "Third U.S. carrier arrives",
         "Iran fires drones at a U.S. radar base in Bahrain; a third "
         "carrier arrives.", ORANGE, "ship"),
        ("EUROPE \u2014 MIGRATION", "Five EU states plan Rwanda hub",
         "Germany, Denmark, Austria, Greece and the Netherlands agree "
         "a joint facility.", BLUE, "pin"),
        ("ASIA \u2014 PACIFIC", "Japan scrambles jets",
         "Tokyo protests strongly after two suspected Russian aircraft "
         "violate its airspace.", TEAL, "jet"),
    ]
    for i, (kicker, headline, sub, color, icon) in enumerate(stories):
        x = MARGIN + (i % 2) * (col_w + 16)
        y = grid_y + (i // 2) * (row_h + 12)
        story_card(cv, x, y, col_w, row_h, kicker, headline, sub,
                   color, icon)

    # Also today
    ay, ah = 882, 100
    cv.fill_rect(MARGIN, ay, W - 2 * MARGIN, ah, NAVY)
    cv.fill_rect(MARGIN, ay, 10, ah, RED)
    ax = MARGIN + 26
    aw = W - 2 * MARGIN - 26 - 16
    label = "ALSO TODAY  \u2014  "
    label_w = text_width(label, FONT_SANS, 1)
    items = ("UK, Australia, Canada & Italy urge Israel to open Gaza "
             "crossings  \u2022  UK sanctions Israeli settlement firms  "
             "\u2022  US curbs AI-chip sales to China  \u2022  Depardieu "
             "admits a sexual-assault charge  \u2022  Eritrea declared "
             "free of trachoma")
    words = items.split()
    line1, i = "", 0
    while i < len(words):
        trial = f"{line1} {words[i]}".strip()
        if text_width(trial, FONT_SANS, 1) <= aw - label_w:
            line1, i = trial, i + 1
        else:
            break
    lines = [line1] + wrap(cv, " ".join(words[i:]), FONT_SANS, 1, aw)[:2]
    draw_text(cv, ax, ay + 12, label, FONT_SANS, H_SANS, 1, GOLD)
    cy = ay + 12
    for j, line in enumerate(lines):
        xx = ax + label_w if j == 0 else ax
        draw_text(cv, xx, cy, line, FONT_SANS, H_SANS, 1, (235, 238, 244))
        cy += 25

    # Footer (kept clear of the bottom border, which sits at y 1016).
    draw_text_anchor(cv, W // 2, 988,
                     "All stories reported on Tuesday 17 November 2026  "
                     "\u2022  Drawn entirely in code",
                     FONT_SANS, H_SANS, 1, GREY, anchor="mm")

    # Border
    cv.rect_outline(2, 2, W - 4, H - 4, NAVY, 4)

    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    out_path = Path(out_dir) / "entry.png"
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_bytes(png_bytes(cv))
    print(f"Wrote {out_path} ({out_path.stat().st_size} bytes)")


if __name__ == "__main__":
    main()
